const html: string = "<div>\n        <p>\n          <span>1. Основні положення&#160;</span>\n        </p>\n        <p>\n          <span>1.1. Ставки приймаються виключно у осіб віком від 21 року.\n            Якщо законодавство юрисдикції Клієнта встановлює вищий\n            мінімальний вік для участі в азартних іграх, застосовується такий\n            вищий вік. Реєстрація, депозит або ставка молодшою особою\n            21 року (або молодше віку, обов'язкового за законом юрисдикції\n            Клієнта) є грубим порушенням Правил: Компанія має право закрити\n            рахунок, анулювати ставки та утримати кошти без повернення.&#160;</span>\n        </p>\n        <p>\n          <span>\n            1.2.Ставки приймаються лише в осіб, які згодні з правилами,\n            встановленими букмекерською компанією далі (Imba.bet). Будь-яка ставка\n            є підтвердженням того, що клієнт знає ці правила і з\n            ними згоден. Адміністрація має право визнати недійсними\n            ставки, зроблені з порушенням цих Правил. Адміністрація не\n            несе ніякої відповідальності щодо того, коли саме їй\n            стало відомо, чи встановлено згодом, що ставки були\n            зроблено з порушенням Правил.\n          </span>\n        </p>\n        <p>\n          <span>\n            1.3. Адміністрація має право не приймати ставки в осіб, які не\n            що виконують ці правила.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            1.4. У разі виявлення шахрайських дій, пов'язаних із прийомом\n            ставок або фінансовими операціями, адміністрація має право припинити\n            такі дії шляхом визнання ставок недійсними, закриття\n            рахунки без повернення залишку коштів та звернення до\n            правоохоронні органи за фактом вчинення шахрайських\n            дій.\n          </span>\n        </p>\n        <p>\n          <span>\n            1.5. У разі виявлення ставок на випередження (післягол) акаунт\n            блокується без повернення коштів.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            1.6. У разі ставок на \"вилки\" з боку клієнта - обліковий запис\n            блокується без повернення коштів.\n          </span>\n        </p>\n        <p>\n          <span>\n            1.7. Претензії щодо спірних питань приймаються протягом 10 днів\n            після закінчення події на підставі письмової заяви.\n            Остаточне рішення щодо всіх спірних ситуацій приймає\n            адміністрація.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            1.8. Ці правила та зміни до них набирають чинності з дати\n            публікації на сайті та поширюються на всі ставки та дії,\n            зроблені з дати публікації, незалежно від того, чи знають\n            клієнти про набрання чинності цією редакцією правил чи ні. Усі\n            попередні правила вважаються такими, що втратили чинність.\n          </span>\n        </p>\n        <p>\n          <span>\n            1.9.Компанія залишає за собою право закрити ігровий рахунок,\n            анулювати ув'язнені парі та баланс, якщо Компанією буде\n            встановлено, що: а) Учасник парі в момент укладання парі мав\n            інформацією про результат події (договірний матч); b) Учасник закладу\n            є безпосереднім учасником матчу (спортсмени, судді,\n            тренери і т. д.) або особою, яка діє за згодою з ним; c) парі\n            укладені групою Учасників парі, що діють узгоджено\n            (синдикатом), з метою перевищити встановлені Компанією обмеження;\n            d) один Учасник закладу має кілька ігрових рахунків; e) Учасник\n            парі підозрюється у використанні спеціального програмного\n            забезпечення або технічних засобів, що дозволяють автоматизувати\n            процес укладання парі; f) були використані будь-які недобросовісні\n            способи отримання інформації чи обходу обмежень, встановлених\n            Компанією; g) існують причини вважати, що ігровий рахунок\n            використовується не для укладання парі та іншої діяльності, пов'язаної\n            з іграми. Залишок на рахунку Учасника парі у вищеописаних ситуаціях\n            підлягає перерахунку та розглядається індивідуально.\n          </span>\n        </p>\n        <p>\n          <span>2. Поповнення депозиту та отримання виграшів</span>\n        </p>\n        <p>\n          <span>\n            2.1. Ставки приймаються на основі лінії – списку майбутніх подій\n            із запропонованими букмекерською конторою котируваннями - коефіцієнтами\n            виграшу. Котирування можуть змінюватися після будь-якої ставки, але умови\n            раніше зроблених ставок залишаються незмінними. Перед ставкою гравці\n            повинні з'ясувати всі зміни лінії.\n          </span>\n        </p>\n        <p>\n          <span>\n            2.2. Зроблені ставки, після розміщення їх на сервері та отримання\n            гравцем повідомлення про прийом ставки та номери купона, на вимогу\n            гравця скасування або виправлення не підлягають, однак, згідно з п. 4.5\n            цих Правил можуть бути анульовані адміністрацією. Обрив\n            з'єднання або інші збої в комунікаціях не є підставою\n            для скасування ставки, якщо ставка зареєстрована на сервері. Ставки\n            приймаються лише у сумі, що не перевищує поточний залишок на рахунку\n            клієнта. Після реєстрації ставки, сума ставки списується з\n            рахунки. Після розрахунку ставок сума виграшу заноситься на рахунок клієнта\n            .\n          </span>\n        </p>\n        <p>\n          <span>\n            2.3. Розрізняються такі типи ставок: &quot;одиночна&quot;,\n            &quot;експрес&quot; та &quot;система&quot;. Поодинока ставка -\n            ставка, у якій потрібно передбачити результат лише події.\n            Поодинокі ставки приймаються на будь-яку подію. Виграш по одиночним\n            ставкам дорівнює сумі ставки помноженої на коефіцієнт виграшу.\n            Експрес - ставка, в якій потрібно передбачити результат більш ніж\n            однієї події одночасно. Якщо хоча б одна подія в\n            експресі вгадано невірно, весь експрес вважається програним. У\n            експрес можна включати будь-яку комбінацію подій будь-яких видів спорту.\n            В експрес не можна включати залежні події: одна й та сама подія\n            не може брати участь в експресі більше одного разу, не можна пов'язувати\n            в експресі результат матчу та ставки на команду, яка бере участь у цьому\n            матчі (наприклад: прохід у наступне коло тощо). Якщо в експресі\n            виявились залежні події, то для цілей розрахунку залишається тільки\n            одна з них, має найбільший коефіцієнт. Коефіцієнт виграшу\n            експреса обчислюється шляхом перемноження коефіцієнтів виграшу всіх\n            подій, що входять до експрес. Виграш за експресами дорівнює сумі\n            ставки помноженої на коефіцієнт виграшу експресу Коефіцієнт\n            виграшу не обмежений. Система – повна комбінація експресів\n            заданого розміру із заздалегідь визначеної кількості подій\n            (максимальна кількість подій у системі – 16). Кожна комбінація\n            у системі розраховується як окремий експрес.\n          </span>\n        </p>\n        <p>\n          <span>\n            2.4. Мінімальна ставка визначається адміністрацією. Максимальна\n            виплата на одну ставку по лінії - 3 млн рублів, у лайві - 1 млн\n            карбованців. Для ставок в іншій валюті максимальна виплата визначається\n            перерахунком за курсом контори. Для деяких категорій ігор та ставок\n            можуть бути встановлені спеціальні ліміти на максимальні виграші,\n            які зазначаються у відповідних розділах цих Правил.\n          </span>\n        </p>\n        <p>\n          <span>\n            2.5. Адміністрація має право обмежувати максимальну ставку на\n            окремі події, а також обмежувати чи підвищувати максимальну\n            ставку конкретному клієнту без повідомлення та пояснення причин.\n            Адміністрація має право обмежити чи відмовити конкретним\n            клієнтам у доступі до наданих сервісів або послуг без\n            повідомлення та пояснення причин.\n          </span>\n        </p>\n        <p>\n          <span>\n            2.6. Ставки приймаються на початок події. Якщо по\n            будь-яким причинам ставку зроблено після фактичного початку\n            Така ставка вважається недійсною. Виняток\n            складають ставки на &quot;Live&quot;-події, тобто ставки по\n            ходу матчу. Такі ставки вважаються дійсними, якщо вони зроблені\n            до закінчення матчу.\n          </span>\n        </p>\n        <p>\n          <span>\n            2.7. Адміністрація залишає за собою право анулювати\n            \"Live\"-ставку, якщо в Адміністрації виникають підозри, що клієнт\n            на момент ставки володів інформацією про результат події, зазначеної в\n            ставці. При цьому Адміністрація не зобов'язана доводити причину\n            виникнення таких підозр &#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            2.8. Якщо у процесі оформлення &quot;Live&quot;-ставки клієнт\n            погодився із зміною коефіцієнтів або параметрів ставки (фора,\n            тотал і т.п.), то ставка приймається, навіть якщо рахунок події\n            змінився на момент реєстрації ставки.\n          </span>\n        </p>\n        <p>\n          <span>3.Особливості розрахунку ставок&#160;</span>\n        </p>\n        <p>\n          <span>\n            3.1.Дата та час початку події, що вказуються в лінії, носять\n            інформативний характер. Помилково вказана дата, час або\n            додаткова інформація (статус або стадія турніру, рахунок першого\n            матчу і т.п.) не є підставою для скасування ставки. У випадку\n            якщо подія відбулася раніше чи пізніше спочатку оголошеною\n            дати, результат вважається дійсним, а ставки вважаються\n            дійсними, якщо вони зроблені на початок події. У випадку\n            перенесення події, що не почалася, на 3 і більше діб ставки\n            повертаються. У разі перенесення не розпочатої події менш ніж на\n            3 доби ставки зберігають силу, але адміністрація має право прийняти\n            рішення про повернення ставок, не чекаючи закінчення події, про що\n            гравці інформуються у офіційних результатах. Якщо матч НБА, НХЛ,\n            МЛБ чи НФЛ не відбулося чи не дограно у призначений день, то\n            повернення ставок провадиться відразу ж наступного дня, крім\n            випадків, коли дату події було вказано помилково.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.2. У списку подій на першому місці вказана команда на полі\n            якою проводиться матч. У разі проведення матчу на полі команди,\n            вказаною на другому місці у списку подій (крім матчів команд з\n            одного міста або області), ставка на цей матч повертається, а з\n            експресів виключається. Проведення матчу на нейтральному полі не\n            є основою скасування ставок. У разі вказівки у назві\n            змагання у лінії місця проведення турніру, допускається запис\n            спортсмена чи команди господарів не першою. У цьому випадку ставки не\n            підлягають поверненню.&#160;\n          </span>\n        </p>\n        <p>\n          <span>3.3. Перервані події: </span>\n        </p>\n        <p>\n          <span>\n            3.3.1. Подія вважається такою, що відбулася, якщо її перервати і\n            грав принаймні певну частину регламентованої правилами гри\n            повний робочий день. Для ставок на матч в цілому це: футбол - 65 хв.\n            (якщо формат матчу не стандартний, то 70 відсотків гри\n            час); баскетбол - 35 хв. (для НБА та інших турнірів з\n            48 хв матчів) і 28 хв. для турнірів з 40-хвилинними матчами;\n            хокей - 45 хв.; Хокк з мячом - 60 хв.; Американський футбол - 50\n            хв; бейсбол - 5 подач; інші види спорту - не менше 70%\n            час відтворення. Винятком є випадки рівних балів на\n            момент зупинки матчів у тих видах спорту, де регламент не дозволяє\n            нічия (баскетбол, бейсбол, американський футбол тощо). У цих\n            У таких випадках подія вважається такою, що не відбулася. Якщо подія розпізнається\n            не вдалося, то ставки на «Пас» повертаються. Якщо подія\n            визнані дійсними, то ставки на «Пас» розраховуються згідно\n            фактичний рахунок на момент зупинки гри, а також у разі нічиєї\n            рахунки - повернення. Для заходів, що проводяться під егідою найбільшого\n            міжнародних організацій (наприклад, ФІФА та УЄФА у футболі), коли в\n            Інформація про терміни події швидко з'являється у відкритому доступі.\n            завершення гри (до 30 годин), за рішенням адміністрації всі ставки можуть\n            розраховувати за кінцевим результатом. Для ставок на\n            окремі частини матчу (чверті в баскетболі, тайми у футболі,\n            періоди в хокей тощо), якщо вони були перервані,\n            тоді вони зараховуються як зіграні, якщо пройдено принаймні 70%.\n            час гри, регламентований правилами цієї частини\n            матч. Розрахунок часу гри враховується лише\n            цілі зіграні хвилини та округлення дробів у меншу сторону.\n            Наприклад, хокейний матч був перерваний на 14-й хвилині деяких\n            періоду, тоді як було зіграно 13 хвилин 20 секунд. В даному випадку\n            Було зіграно 13 повних хвилин, що становить 65%, тобто менше,\n            ніж 70%. Тому ставки на цей період підлягають скасуванню.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.3.2. Перервана подія, що не підпадає під визначення\n            події, що відбулася, може бути визнано недійсною, якщо вона\n            не дограно протягом 3-х годин.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.3.3. Для перерваних подій, визнаних такими, що не відбулися, поверну\n            підлягають усі ставки, крім ставок, результат яких на момент\n            зупинки події однозначно визначено (наприклад, хто заб'є 1-й\n            гол, отримає ж/карту, відбувся тотал «на більше» тощо). Для\n            перерваних подій підлягають безумовному поверненню ставки на\n            порівняльну результативність таймів (періодів та ін.).\n          </span>\n        </p>\n        <p>\n          <span>\n            3.3.4 Перервані події, визнані такими, що відбулися, розраховуються\n            на загальних засадах. Ставки в перерваному матчі (грі, змаганні та\n            т.д.), відлік розіграшу яких не розпочався (наприклад, гол із 76 по 90\n            хв, якщо матч перервано на 70-й хвилині), підлягають поверненню. Ставки на\n            початі, але не завершені події (наприклад, чи буде гол в\n            інтервалі з 61 по 75 хв, якщо матч перервано на 70-й хвилині)\n            розраховуються як такі, що відбулися.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.3.5 З окремих видів спорту можливі додаткові особливості\n            розрахунку ставок, якщо вони вказані у відповідних пунктах правил.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.4. Якщо початковий результат завершеної події пізніше\n            скасовано з якихось причин, скасування до уваги не береться, та\n            ставки підлягають оплаті відповідно до початкового (фактичного)\n            результатом. Фактичним вважається результат, оголошений на\n            на підставі офіційних протоколів та інших офіційних джерел\n            інформації безпосередньо після завершення події. У випадку\n            відсутності результатів в офіційних джерелах адміністрація має право\n            використовувати альтернативні джерела інформації, зокрема\n            інформацію свого представника на матчі. Якщо в лінії в\n            назві змагання явно вказано джерело (наприклад,\n            телетрансляція), то він є пріоритетним щодо\n            результату. Якщо подія перервана і наступного дня грає з\n            самого початку, то для цілей розрахунку перший матч вважається перерваним\n            подією та розраховується згідно з п 3.3\n          </span>\n        </p>\n        <p>\n          <span>\n            3.5. Адміністрація має право оголосити ставку недійсною\n            у випадках:\n          </span>\n        </p>\n        <p>\n          <span>\n            3.5.1 Помилок персоналу або програмних збоїв під час прийому ставок\n            (очевидні друкарські помилки в коефіцієнтах, невідповідність коефіцієнтів в\n            різних позиціях тощо)\n          </span>\n        </p>\n        <p>\n          <span>\n            3.5.2 За наявності очевидних ознак неспортивної боротьби. У випадку\n            виникнення підозр у неспортивному характері матчів у Fonbet\n            або у міжнародних організацій щодо їх попередження EWS-FIFA,\n            Federbet та Tennis Integrity Unit, адміністрація має право\n            заблокувати ставки Клієнта, який зробив підозрілу ставку до\n            висновки міжнародної організації, та визнати ставки\n            недійсними у разі встановлення їй факту неспортивного\n            боротьби. Адміністрація не зобов'язана надавати гравцям докази\n            та висновки.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.5.3 Виявлення шахрайських дій, пов'язаних із прийомом ставок\n            чи операціями, пред'явленням підроблених документів;\n          </span>\n        </p>\n        <p>\n          <span>\n            3.5.4 Підтвердження факту гри з чужого облікового запису або виникнення\n            підозр щодо використання особистого кабінету сторонніми особами.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.5.5 Відмова від проходження процедури верифікації, а також у разі\n            підтвердження факту повторної реєстрації (у тому числі, використовуючи\n            чужі персональні дані, документи, зокрема. недійсні та\n            підроблені).\n          </span>\n        </p>\n        <p>\n          <span>3.5.6 Інших випадках порушення цих правил.</span>\n        </p>\n        <p>\n          <span>\n            3.6. У разі, якщо ставку визнано недійсною, відбувається\n            повернення цієї ставки, а якщо вона включена в експрес чи систему, то\n            з метою розрахунку вона враховується з коефіцієнтом 1.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.7. Усі поточні результати, час гри, інша додаткова\n            інформація, які відображаються на сайті, служать лише як\n            довідкова інформація. Адміністрація прагне, щоб інформація\n            була точною, проте не несе відповідальності за наслідки ставок,\n            зроблених на підставі цієї інформації. Клієнту рекомендується при\n            перевірки правильності розрахунку ставок, у тому числі live-ставок,\n            використовувати офіційні джерела інформації (офіційні сайти\n            організаторів спортивних заходів).\n          </span>\n        </p>\n        <p>\n          <span>\n            3.8. Одночасні ставки, а також ставки, що дозволяють обійти\n            існуючі максимальні розміри ставки або виплати, на один і той\n            ж результат від групи осіб (синдикату гравців тощо) не допускаються. Не\n            дозволяється ставити повторні ставки на ту саму комбінацію\n            результатів у разі, якщо сумарна потенційна виплата перевищує\n            максимальну. Адміністрація має право оголосити такі ставки\n            недійсними.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.9. Будь-яка зміна рахунку та інших параметрів матчу, спричинена\n            офіційним суддівським рішенням (наприклад, скасування голу через офсайд,\n            після відео-перегляду, скасування або перегляд очка в тенісі,\n            волейболі та ін.) або взаємною домовленістю учасників (наприклад,\n            гра в рівних складах після видалення та ін.) не є підставою\n            для скасування ставок.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.10. У спірних ситуаціях, які не мають прецеденту, остаточне\n            рішення приймає букмекерська контора (Imba.bet).\n          </span>\n        </p>\n        <p>\n          <span>4. Основні види ставок&#160;</span>\n        </p>\n        <p>\n          <span>\n            4.1. Ставки на фактичний результат. Можна зробити ставки на матчі без\n            обліку фори, якщо вказано відповідні коефіцієнти (на першій\n            позиції – за виграш першої команди (&quot;1&quot;), на другій\n            позиції - коефіцієнт за нічию \"Х\", на третій позиції -\n            коефіцієнт за виграш другої команди (&quot;2&quot;). У цьому\n            У разі, результатом ставки є фактичний результат матчу. Також\n            можна зробити ставку на те, що перша команда не програє\n            (&quot;1X&quot;), 2-а команда не програє (&quot;X2&quot;) чи не\n            буде нічиєю (&quot;12&quot;).\n          </span>\n        </p>\n        <p>\n          <span>\n            4.2. Ставки на перемогу кожної з команд у матчі з урахуванням фори\n            (Гандакапа). Фора визначається букмекерською конторою і може бути\n            позитивною, негативною або рівною нулю. Для визначення\n            результату ставки до фактично забитих голів команди, на яку\n            зроблено ставку, віднімається (якщо фора негативна) або\n            додається (якщо позитивна фора) фора на обрану команду\n            (Фора на другу команду до уваги не береться). Якщо після\n            цього результат матчу виходить на користь обраної команди, то\n            ставка вважається виграною. У разі нічийного результату – ставка\n            повертається. Наприклад, якщо на першу команду встановлено\n            негативна фора &quot;-1&quot;, і матч закінчився: а) з рахунком\n            0:0, ставку програно; б) з рахунком 1:0, ставка повертається; в) з\n            рахунком 2:0, ставку виграно. A якщо встановлено позитивну фору\n            &quot;+0.5&quot; і матч закінчився а) з рахунком 0:1, ставка\n            програно; б) з рахунком 0:0 або 1:0, ставку виграно.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.3. Азіатський Гандікап. Ставка на перемогу або тотал з урахуванням фори\n            (Гандікапа), кратного 0.25 (але не кратного 0.5). Така ставка\n            розраховується, як дві ставки у розмірі половини суми, з\n            однаковими коефіцієнтами, та з найближчими значеннями &quot;звичайних\n            фор&quot; та «звичайних тоталів» (цілочисельними, або кратними 0.5).\n            Такі події в лінії позначаються префіксом Asian. Якщо\n            ставку з азіатським гандикапом включено в експрес або систему, то\n            при розрахунку цієї ставки використовується коефіцієнт виграшу, який\n            б вийшов при її розрахунку в одинарі. У разі виграшу обох\n            половинних ставок при розрахунках враховується коефіцієнт ставки (К).\n            Якщо одна половинна ставка виграла, а за іншою витрату, в розрахунку\n            приймається коефіцієнт (К+1)/2. Якщо одна половинна ставка\n            програла, а за іншою витратою, в експресах вважається коефіцієнт\n            0,5. Якщо обидві половинні ставки програно, то вся ставка вважається\n            програної.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.4. Ставки на загальну кількість голів, очок, кутових, штрафних,\n            карток та інших подій, встановлених конторою (&quot;Більше -\n            Менше”. Кількість вищезазначених подій визначається як\n            загальне значення називається «тотал» і визначається конторою. У випадку\n            влучення в тотал ставка повертається.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.5. Ставки на перемогу у змаганнях чи вихід у наступне коло\n            турнірів. Якщо заявлений у змаганні учасник з будь-якої\n            причині не зміг розпочати змагання, ставки на цього учасника\n            підлягають поверненню. Якщо два або більше учасників поділили\n            перемогу у змаганні, виграш на кожного з них виплачується\n            виходячи з коефіцієнта виграшу, розрахованого за формулою\n            К=(Кисх-1)/N+1, де Кисх-вихідний коефіцієнт на учасника,\n            N-кількість переможців змагання.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.6. Ставки на конкретний рахунок матчу та тайм-матч. У ставці виду\n            &quot;тайм-матч&quot; необхідно вгадати одночасно результат першого\n            тайму та всього матчу. У лінії для позначення цих результатів\n            використовуються початкові літери: П – перемога, Н – нічия, при цьому на 1-му\n            місці ставиться результат 1-го тайму, але в другому - матчу. Вихід 2-го\n            тайму для розрахунку цієї ставки значення НЕ має. Наприклад, якщо матч\n            закінчився з рахунком 1:1, а перший тайм 1:0, то виграє результат\n            П1Н.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.7. Ставки на статистику туру чи ігрового дня. Якщо в\n            турі визнано таким, що не відбувся (за критеріями п.4.3) або скасовано (за\n            критеріям п.4.1) хоча б один матч, то ставки на турову статистику\n            підлягають поверненню, окрім ставок, результат яких однозначно\n            визначено (наприклад, чи буде нічия 0:0, всі команди заб'ють тощо).\n            Букмекерська контора має право прийняти рішення про повернення ставок на\n            статистику туру або ігрового дня у разі появи достовірної\n            інформації про відміну одного з матчів до початку туру, про що гравці\n            інформуються у офіційних результатах. Для розрахунку показників на\n            ігровий день тенісних матчів гравцю, який не дограв матч\n            будь-якій причині), у всіх сетах і геймах, що залишилися, зараховується\n            поразка. Господарями вважаються команди чи гравці, зазначені у лінії\n            першому місці.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.8. Ставки на пар або брак загальної кількості голів або очок в\n            матчі. Коефіцієнти вказані у лінії. Рахунок 0:0 - чет.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.9. Ставки на індивідуальні показники чи порівняння гравців\n            (учасників). Якщо гравець не виходив на поле (не брав участі), то\n            ставки на події за його участю підлягають поверненню. Для учасників,\n            які не закінчили подію, розрахунок показників здійснюється за\n            фактичному результату на момент зняття (сходу) і для цілей\n            розрахунку таким учасникам присвоюється останнє місце у підсумковому\n            протоколі. Ставки &quot;буде хет-трик&quot; вважаються\n            виграними, якщо гравець забив три або більше голів. Ставки &quot;буде\n            чи дубль&quot; вважаються виграними, якщо гравець забив два або більше\n            гола. У ставках на показники гравців голи, забиті гравцем у свої\n            ворота, у його показниках не враховуються. У ставках, які стосуються\n            командної результативності, голи, забиті командою у свої ворота,\n            враховуються як забиті її опонентом. Особливості розрахунку ставок на\n            показники гравця у тенісі зазначені у п.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.10. У неігрових видах спорту (лижі, біатлон, легка атлетика та\n            т.д.) у порівняннях &quot;Хто вище&quot; якщо учасник (для естафети\n            - команда) стартував, але не фінішував, то ставки на нього в\n            в порівнянні з іншим учасником програють. Якщо обидва учасники зійшли\n            з дистанції чи один із учасників не стартував - повернення ставок.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.11. Ставки на результат таймів, періодів, чвертей тощо. У випадку\n            якщо подія була визнана такою, що не відбулася, але перший тайм (період і\n            т.п.) завершився, то ставки на перший тайм розраховуються у звичайному\n            порядку, навіть якщо ставки на подію загалом підлягають поверненню.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.12. Ставки на час, коли станеться та чи інша подія,\n            наприклад, час 1-го гола, час 1-ї ж/карти, час лідирування\n            однією з команд тощо. Пропонується вгадати порядкову хвилину, на\n            якою станеться подія. Точний час для розрахунку таких ставок\n            визначається без урахування секунд. Наприклад, час 1-го гола, якщо\n            перший гол забитий коли з початку матчу пройшло 00х10сек – «1-а\n            хвилина», 04х10сек – «5-а хвилина», 04мин59сек – «5-а хвилина»,\n            05хв00сек – «6-а хв».\n          </span>\n        </p>\n        <p>\n          <span>\n            4.13. Ставки на показники, виражені у відсотках (% першої подачі,\n            % володіння м'ячем і т.д.) Для розрахунку береться значення показника з\n            офіційного сайту, заокруглене до цілого за правилами арифметики.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.14. Ставки на кількість одного показника (п1), які будуть\n            передувати наступу іншого показника (п2). Наприклад\n            &quot;кількість ударів у створ до першого голу&quot;,\n            &quot;кількість фолів до першої ж/карти&quot; і т.п. Удар у площину,\n            з якого забитий гол, або фол, за який дали ж/картку, рахується.\n            Якщо голів або ж/карт не було, то результатом є загальне\n            кількість показників п1 (тобто. загальна кількість ударів у площину або\n            голів).\n          </span>\n        </p>\n        <p>\n          <span>5. Прийом ставок під час матчу (live-ставки)</span>\n        </p>\n        <p>\n          <span>\n            5.1. Live-ставки приймаються на основні та додаткові результати.\n            Можна робити одиночні live-ставки або об'єднувати їх в один\n            експрес.\n          </span>\n        </p>\n        <p>\n          <span>\n            5.2. Ставка вважається прийнятою після її реєстрації на сервері та\n            видачі підтвердження онлайн. Ухвалена ставка зміні не підлягає.\n            У разі настання обставин, зазначених у розділі «Основні\n            правила прийому ставок», можливий розрахунок live-ставки з коефіцієнтом\n            \"1\".\n          </span>\n        </p>\n        <p>\n          <span>\n            5.3. Букмекерська компанія не несе відповідальності за неточності в\n            поточні результати матчів, за якими приймаються live-ставки.\n            Клієнти повинні також користуватись іншими незалежними джерелами\n            інформації.\n          </span>\n        </p>\n        <p>\n          <span>5.4. Live-ставки не редагуються та не видаляються.</span>\n        </p>\n        <p>\n          <span>\n            6. Результати матчів, дата та час їх початку, порядок вирішення\n            спірних питань\n          </span>\n        </p>\n        <p>\n          <span>\n            6.1. Розрахунок ставок може бути переглянутий у зв'язку з невірним\n            результатом, наданим букмекером. При розрахунку ставок\n            береться до уваги фактичний час початку подій, який\n            орієнтовно визначається на підставі офіційних документів\n            організацій, які проводять спортивні змагання, і якщо немає таких\n            затверджених документів, то на підставі офіційних сайтів\n            спортивних федерацій, сайтів спортивних клубів та інших джерел\n            спортивної інформації\n          </span>\n        </p>\n        <p>\n          <span>\n            6.2. Букмекерська компанія не несе відповідальності за\n            невідповідність дати та часу реальному початку подій. Дата та час\n            початку події, що вказуються в лінії, мають орієнтовний характер.\n            При розрахунку ставок приймається фактичний час початку події,\n            яке визначається на підставі офіційних документів\n            організації, яка проводить змагання.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.3. Букмекерська компанія не несе відповідальності за неточності в\n            назві чемпіонатів та тривалості матчів (спортивних\n            подій). Дані, що вказуються в лінії та прямій трансляції, носять\n            орієнтовний характер. Клієнтам необхідно користуватися іншими\n            незалежними джерелами інформації для уточнення даних щодо\n            спортивної події Претензії за результатом події приймаються у\n            протягом 10 днів з моменту завершення події за наявності офіційних\n            документів за результатом події, виданих організацією, що проводить\n            змагання.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.4. Ставки, зроблені після початку події, розраховуються з\n            коефіцієнтом \"1\" (за винятком live-ставок); в експресах\n            коефіцієнт за такими ставками вважається рівним «1».\n          </span>\n        </p>\n        <p>\n          <span>\n            6.5. Якщо клієнт зробив ставку на подію, результат якої йому\n            був відомий, така ставка підлягає скасуванню. У цьому випадку рішення\n            букмекерською компанією приймається після спеціального закритого\n            розслідування. Усі дії щодо такої ставки тимчасово\n            припиняються.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            6.6. Якщо учасник відмовляється від боротьби до початку події, то все\n            ставки цього учасника анулюються.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.7. Якщо учасник з будь-якої причини (травма, відмова тощо)\n            вибуває по ходу змагання, то всі ставки, зроблені на початок\n            останнього раунду або етапу змагання, в якому він брав участь,\n            вважаються дійсними, а решта ставок анулюється.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            6.8. Якщо учасник, член команди (футболіст, хокеїст, баскетболіст\n            і т.д.) не брав участі у матчі, коефіцієнт виграшу за ставками\n            нього приймається рівним «1», а то й обумовлено інше.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.9. Якщо у тенісному матчі відмова (дискваліфікація) відбулася до\n            початку матчу, коефіцієнт виграшу за ставками приймається рівним\n            «1», окрім ставок на результат учасника у змаганні. Якщо\n            тенісний матч перервано, не завершено в той же день і відкладено, ставки\n            на нього залишаються чинними до закінчення турніру, в рамках якого цей\n            матч проводився, поки матч не буде дограно або не відбудеться відмова\n            одного з учасників.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            6.10. Якщо у події (матчі, змаганні чи бою) вказується одна\n            пара учасників (команд, спортсменів), а згодом склад пари\n            змінюється, то всі ставки на цю подію скасовуються.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.11. У командних змаганнях при заміні одного чи кількох\n            учасників будь-якої з команд з будь-якої причини, ставки на результат всього\n            матчу залишаються в силі.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            6.12. У парних матчах якщо вказано склад пар, при заміні хоча б\n            одного з учасників коефіцієнт виграшу за ставками дорівнюватиме\n            \"1\". Якщо склад не вказано, ставки залишаються чинними.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.13. У змаганнях, у яких використовуються поняття «господарі» та\n            «гості», у разі перенесення події: на нейтральне поле – ставки\n            зберігають чинність; на полі команди-суперника – ставки зберігають чинність.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.14. Якщо поняття «господарі» та «гості» не застосовуються для події\n            (наприклад, в одиночних та парних видах спорту), то при зміні\n            місця проведення події всі ставки на нього зберігають чинність. Команди\n            NBA, NHL, AHL, CHL, OHL, WHL, Хокейна Ліга Східного узбережжя\n            Північної Америки можуть розташовуватися як у прямій послідовності\n            (господарі – гості), і у зворотній. У разі зворотного розташування\n            повернення за ставками не провадиться.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.15. У товариських матчах клубних товариських турнірах при\n            зміну місця проведення події всі ставки на нього зберігають\n            силу.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.16. Види спорту чи ситуації, для яких не існує окремого\n            описи особливостей прийому та розрахунку ставок, що підпорядковуються Загальним\n            правилам.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.17. У спірних ситуаціях, які не мають прецеденту, остаточне\n            рішення ухвалюється букмекерською компанією.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.18. У разі невідповідності даних із різних джерел\n            інформації (дати, часу, результату, назви команди)\n            букмекерська компанія зупиняє виплату виграшу до повного\n            розгляду справжності таких відомостей. Якщо результат\n            завершеної події, представленої на офіційному сайті,\n            відрізняється від даних телевізійної трансляції, то Компанія залишає\n            за собою право проводити розрахунок за даними телевізійної\n            трансляції.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            6.19. У разі виявлення помилки у програмі виведення коефіцієнтів та\n            визнання цієї помилки компанією, всі зроблені ставки за цим\n            подіям вважаються виграшними і виплата за ставками провадиться з\n            коефіцієнтом виграшу, що дорівнює «1».\n          </span>\n        </p>\n        <p>\n          <span>7. Сторони&#160;</span>\n        </p>\n        <p>\n          <span>\n            7.1. Усі пункти Угоди, що включають займенники «ми», «нас»,\n            \"наш\" або \"Компанія\", відносяться до Компанії, з якою клієнт\n            укладає договір, відповідно до наведеного вище пункту 1.\n          </span>\n        </p>\n        <p>\n          <span>8. Зміна умов</span>\n        </p>\n        <p>\n          <span>\n            8.1. По ряду причин, а саме: комерційним, юридичним, а також\n            причин, пов'язаних з обслуговуванням клієнтів, ми маємо право\n            вносити будь-які зміни до Угоди. Актуальні пункти Угоди та\n            дати їх набрання чинності представлені на сайті. Клієнт несе особисту\n            відповідальність за ознайомлення з чинною Угодою. У\n            Компанії є право вносити зміни в роботу Інтернет-сайту\n            будь-який час та без попереднього інформування Клієнтів.\n          </span>\n        </p>\n        <p>\n          <span>\n            8.2. У разі незгоди зі зміненими пунктами Угоди Клієнт\n            повинен припинити використання веб-сайту. Подальше використання\n            Веб-сайту, після набрання чинності зміненими пунктами Угоди,\n            буде розцінюватися як його повне прийняття, незалежно від того,\n            отримав Клієнт відповідне повідомлення або дізнався про\n            зміни з оновленої Угоди.\n          </span>\n        </p>\n        <p>\n          <span>9. Право вимоги</span>\n        </p>\n        <p>\n          <span>\n            9.1. Особам, які не досягли 21-річного віку або віку (далі —\n            Допустимий вік), який є обов'язковим для законного\n            участі в азартних іграх за законодавством конкретної юрисдикції\n            (якщо він вищий за 21 рік), заборонено користуватися Веб-сайтом.\n            Використання Веб-сайту особами, які не досягли Допустимого віку,\n            є прямим порушенням Угоди. У зв'язку з цим у нас є\n            право у будь-який час вимагати документи, які можуть підтвердити\n            вік та особистість Клієнта. Клієнту може бути відмовлено у\n            надання послуг, дія його рахунку може бути припинена\n            або припинено, ставки та виграші анульовані, а залишок коштів\n            утриманий без повернення, якщо на нашу вимогу не буде пред'явлено\n            докази того, що вік Клієнта відповідає\n            Допустимому, або якщо буде встановлено, що Клієнт не досяг\n            Допустимого віку.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            9.2. Азартні онлайн-ігри заборонені законом у деяких юрисдикціях.\n            Ухвалюючи Угоду, Клієнт усвідомлює, що Компанія не може\n            надати гарантії або юридичну консультацію щодо\n            легітимності використання Веб-сайту на території юрисдикції,\n            якої знаходиться Клієнт. Ми не можемо стверджувати, що послуги\n            Веб-сайту не порушують закони юрисдикції Клієнта. Клієнт користується\n            послугами Веб-сайту за власним бажанням та бере на себе повну\n            відповідальність, добре усвідомлюючи усі можливі ризики.\n          </span>\n        </p>\n        <p>\n          <span>\n            9.3. Ми не прагнемо і не маємо наміру надати Клієнту послуги,\n            що порушують законодавство його юрисдикції. Приймаючи Угоду,\n            Клієнт підтверджує та гарантує, що використання Веб-сайту\n            відповідає законам та правилам, що діють на території його\n            юрисдикції. Ми не несемо відповідальності за незаконне користування\n            послугами Веб-сайту.\n          </span>\n        </p>\n        <p>\n          <span>\n            9.4. З юридичних причин ми не приймаємо Клієнтів з наступних\n            країн:\n          </span>\n        </p>\n        <p>\n          <span>\n            9.4.1. Абсолютне обмеження. Не приймаються клієнти із США,\n            Канади, Великобританії, Іспанії, Латвії, Литви, Нідерландів,\n            Франції, Італії, Швейцарії, Албанії, Барбадосу, Пакистану, Сирії,\n            Південного Судану, Кайманових островів, Гаїті, Ямайки, Північної Кореї,\n            Мальти та Панами. Особам, які проживають або перебувають на території\n            цих країн, не дозволяється відкривати рахунки або вносити грошові кошти\n            гроші на Веб-сайті. У списку юрисдикцій можливі зміни, і вони\n            можуть бути зроблені Компанією без попереднього повідомлення\n            Клієнтів. Ви погоджуєтесь, що не станете відкривати рахунок або\n            перераховувати на нього кошти, перебуваючи на території однієї\n            з перерахованих вище юрисдикцій.\n          </span>\n        </p>\n        <p>\n          <span>\n            9.4.2. Чорний перелік. На додаток до пункту 9.4.1, усі ігри NetEnt\n            заборонені в таких країнах: Афганістан, Албанія, Алжир, Ангола,\n            Австралія, Камбоджа, Еквадор, Гайана, Гонконг, Індонезія, Іран,\n            Ірак, Ізраїль, Кувейт, Лаос, М'янма, Намібія, Нікарагуа, Північна\n            Корея, Пакистан, Панама, Папуа-Нова Гвінея, Філіппіни, Сінгапур,\n            Південна Корея, Судан, Сирія, Тайвань, Уганда, Ємен, Зімбабве,\n            Бельгія, Болгарія, Данія, Естонія, Латвія, Литва, Чехія, Мексика,\n            Португалія, Румунія.\n          </span>\n        </p>\n        <p>\n          <span>9.4.3. Обмеження для брендових ігор.&#160;</span>\n        </p>\n        <p>\n          <span>\n            9.4.3.1. Ігри Guns &amp; Roses, Jimi Hendrix та Motörhead не\n            обслуговуються в таких країнах: Афганістан, Албанія, Алжир,\n            Ангола, Камбоджа, Еквадор, Гайана, Гонконг, Індонезія, Іран, Ірак,\n            Кувейт, Лаос, М'янма, Намібія, Нікарагуа, Північна Корея, Пакистан,\n            Панама, Папуа-Нова Гвінея, Філіппіни, Сінгапур, Південна Корея, Судан,\n            Сирія, Тайвань, Уганда, Ємен, Зімбабве, Бельгія, Болгарія, Канада,\n            Данія, Естонія, Франція, Італія, Латвія, Литва, Мексика, Португалія,\n            Румунія, Іспанія, Сполучені Штати Америки, Великобританія,\n            Австралія, Азербайджан, Китай, Індія, Малайзія, Катар, Росія,\n            Таїланд, Туніс, Туреччина та Україна.&#160;\n          </span>\n        </p>\n        <p>\n          <span>9.4.3.2. Ігри </span>Universal Monsters (Frankenstein, the Bride\n          of Frankenstein, Dracula, The Phantom's Curse, Creature from the Black\n          Lagoon та The Invisible Man\n          <span>\n            ), обслуговуються ВИКЛЮЧНО в таких країнах: Андорра,\n            Вірменія, Азербайджан, Білорусь, Боснія та Герцеговина, Бразилія,\n            Грузія, Ісландія, Ліхтенштейн, Молдова, Монако, Чорногорія,\n            Норвегія, Росія, Сан-Марино, Сербія, Швейцарія, Україна, Хорватія,\n            Македонія, Туреччина, Австрія, Болгарія, Кіпр, Фінляндія, Німеччина,\n            Греція, Угорщина, Ірландія, Люксембург, Мальта, Нідерланди, Перу,\n            Польща, Словаччина, Словенія та Швеція.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            9.4.4. Обмеження для об'єднаного джекпоту. Об'єднані джекпоти\n            не обслуговуються та не можуть бути доступні в таких країнах:\n            Австралія, Азербайджан, Китай, Данія, Індія, Ізраїль, Італія,\n            Японія, Малайзія, Катар, Росія, Іспанія, Таїланд, Туніс, Туреччина,\n            Об'єднані Арабські Емірати та Україна.\n          </span>\n        </p>\n        <p>\n          <span>9.5. Ставки не приймаються:</span>\n        </p>\n        <p>\n          <span>\n            9.5.1. в осіб, які є учасниками подій, на які робляться\n            ставки (спортсмени, тренери, судді, власники чи функціонери клубів\n            та інші особи, які мають можливість вплинути на результат події), а також\n            в осіб, які діють за їх дорученням; в осіб, які представляють інтереси\n            інших букмекерських компаній;\n          </span>\n        </p>\n        <p>\n          <span>\n            9.5.2. в інших осіб, чия участь в угоді з букмекерською\n            компанією заборонено чинним законодавством.\n          </span>\n        </p>\n        <p>\n          <span>\n            9.6. Відповідальність за порушення пункту 9.5 цієї Угоди\n            несе учасник закладу. У разі порушення цієї Угоди,\n            букмекерська компанія залишає за собою право відмовити в оплаті\n            будь-якого виграшу або у поверненні внесених сум, а також\n            анулювати будь-які ставки. Букмекерська компанія не несе\n            відповідальності&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            щодо того, коли саме їй стало відомо, що клієнт входить\n            до однієї з перерахованих вище категорій осіб. Це означає, що\n            букмекерська компанія має право вживати зазначені заходи до будь-якого\n            час після того, як стало відомо, що клієнт є одним з\n            зазначених осіб.\n          </span>\n        </p>\n        <p>\n          <span>\n            9.7. Якщо учасник парі здійснює шахрайські дії щодо\n            букмекерської компанії (мульти-аккаунт, використання ПЗ для\n            автоматизації ставок, гра на арбітражних ситуаціях, якщо ігровий\n            рахунок не використовується для здійснення ставок, зловживання\n            програмами лояльності і т.д.), то букмекерська компанія залишає\n            за собою право припинити такі шахрайські дії шляхом скасування\n            ставок та закриття ігрового рахунку учасника парі.\n          </span>\n        </p>\n        <p>\n          <span>10. Відкриття рахунку&#160;</span>\n        </p>\n        <p>\n          <span>\n            10.1. Для того, щоб отримати доступ до всіх основних послуг\n            Веб-сайту необхідно відкрити рахунок. Для цього, Клієнт може\n            зробити реєстрацію «в 1 клік» або вказати свою адресу\n            електронної пошти та придумати пароль, який надалі буде\n            використовуватись для входу в ігровий профіль, а також додатково\n            потрібно вказати особисті дані: ім'я, номер телефону та дату\n            народження.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            10.2. Клієнт повинен вказати справжню адресу електронної пошти у\n            процесі реєстрації або, у разі реєстрації «в 1 клік», змінити\n            адресу на справжню.\n          </span>\n        </p>\n        <p>\n          <span>\n            10.3. Для підтвердження достовірності інформації Компанія має\n            право вимагати документи, що підтверджують особу Клієнта. Якщо\n            з будь-яких причин Клієнт не надає запитані для\n            ідентифікації документів, Компанія має право призупинити або\n            заблокувати профіль Клієнта до надання їм необхідної\n            інформації.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            10.4. Клієнт підтверджує, що при реєстрації на Веб-сайті він\n            вказав повну та достовірну інформацію про себе, і в тому випадку, якщо\n            в ній відбудуться якісь зміни, Клієнт зобов'язується\n            негайно внести їх у свій профіль. Невиконання або\n            ігнорування цього правила може призвести до застосування\n            обмежень, зупинення або блокування профілю, а також до\n            анулювання платежів.\n          </span>\n        </p>\n        <p>\n          <span>\n            10.5. У разі виникнення будь-яких питань або проблем при\n            реєстрації на Веб-сайті, Клієнт може звернутися до служби підтримки\n            в режимі онлайн-чату або зателефонувати за номером – 8 (800) 301-77-89\n            (цілодобово).\n          </span>\n        </p>\n        <p>\n          <span>\n            10.6. Кожен Клієнт може відкрити на Веб-сайті лише один рахунок.\n            Інші відкриті Клієнтом рахунки вважатимуться дублікатами. У нас\n            є право закривати подібні рахунки та визнавати недійсними\n            всі операції, проведені з використанням дублюючого рахунку.\n          </span>\n        </p>\n        <p>\n          <span>\n            10.6.1. Не повертати Клієнтам усі вклади та ставки, зроблені з\n            основного та дублюючого рахунку; вимагати повернення всіх\n            виграшів, бонусів та грошових коштів, отриманих при використанні\n            дублюючого рахунку. Клієнт зобов'язаний повернути їх по першому нашому\n            вимогою.&#160;\n          </span>\n        </p>\n        <p>\n          <span>11. Доказ особистості. Легалізація&#160;</span>\n        </p>\n        <p>\n          <span>\n            11.1 Будь ласка, зверніть увагу на те, що ім'я та дата народження,\n            вказані у вашому профілі повинні відповідати вашому\n            дійсне ім'я.\n          </span>\n        </p>\n        <p>\n          <span>\n            11.2 Ім'я, вказане у вашому профілі під час реєстрації, має\n            збігатися з ім'ям на кредитній картці або інших платіжних профілях,\n            використовуваних для поповнення або виведення коштів з/на ваш ігровий\n            рахунок.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            11.3 Для підтвердження вашої особи, адреси та/або платіжного\n            профілю (особи) ми можемо в будь-який час запитати: &#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            11.3.1. підтвердження особи (включаючи, але не обмежуючись, копії\n            дійсного паспорта/посвідчення особи та/або використовуваних\n            платіжних карток),\n          </span>\n        </p>\n        <p>\n          <span>\n            11.3.2. підтвердження адреси, включаючи, але не обмежуючись, недавні\n            рахунки за комунальні послуги (не більше ніж тримісячні\n            давності),&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            11.3.3 довідку з банку про стан рахунків, що належать до обраного\n            методу оплати (не більше ніж тримісячної давності).\n          </span>\n        </p>\n        <p>\n          <span>\n            11.4 Якщо ви не надаєте нам ці документи та/або ми не можемо\n            верифікувати вашу особистість протягом розумного терміну,\n            що визначається нами, ми залишаємо за собою право; &#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            11.4.1 заблокувати профіль Клієнта доти, доки верифікація не\n            буде успішно пройдено;\n          </span>\n        </p>\n        <p>\n          <span>\n            11.4.2 анулювати всі або деякі здійснені вами транзакції\n            і заморозити ваш профіль, та/або заморозити або закрити ваш профіль та\n            припинити дію цієї Угоди.\n          </span>\n        </p>\n        <p>\n          <span>\n            11.5 Ми залишаємо за собою право провести перевірку безпеки у\n            будь-який час для підтвердження інформації про вашу особистість, вік\n            та інших реєстраційних або платіжних даних, наданих вами\n            для верифікації вашого користування послугами (наприклад, для\n            запобігання забороненим діям), дотримання вами даного\n            Угоди та перевірки ваших фінансових транзакцій, що виробляються в\n            рамках використання Послуг, на потенційне порушення цього\n            Угоди.\n          </span>\n        </p>\n        <p>\n          <span>\n            11.6 Ви даєте букмекерській компанії право надсилати будь-які запити\n            щодо вас, використовувати та розкривати будь-якій третій стороні\n            будь-яку інформацію про вас із метою її перевірки.\n          </span>\n        </p>\n        <p>\n          <span>\n            11.7 Ви погоджуєтесь надавати за нашим запитом будь-яку\n            додаткову інформацію або документи для проведення перевірки\n            безпеки.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            11.8 Ця процедура є обов'язковою вимогою і проводиться у\n            відповідно до чинних правил в галузі азартних ігор та\n            законодавчими вимогами щодо боротьби з відмиванням грошей,\n            зокрема, відповідно до Національної Постанови про\n            інформування про нестандартні транзакції та нашої внутрішньої\n            політикою боротьби з відмиванням грошей та запобіганням\n            фінансування тероризму\n          </span>\n        </p>\n        <p>\n          <span>12. Ім'я користувача, пароль та безпека</span>\n        </p>\n        <p>\n          <span>\n            12.1. Після відкриття рахунку на Веб-сайті Клієнт зобов'язаний зберігати свій\n            пароль та ім'я користувача в секреті та не розголошувати дану\n            інформацію третім особам. У разі втрати даних необхідних для\n            отримання доступу до рахунку, їх можна дізнатися або відновити, натиснувши\n            на кнопку \"Відновити пароль\".\n          </span>\n        </p>\n        <p>\n          <span>\n            12.2. Клієнт відповідає за збереження пароля, а також будь-які дії\n            та транзакції, зроблені з його рахунком. Крім того, Клієнт несе\n            відповідальність за всі збитки, завдані ним внаслідок дій\n            третьої сторони.\n          </span>\n        </p>\n        <p>\n          <span>\n            12.3. У разі порушення безпеки та несанкціонованого доступу\n            до рахунку Клієнт повинен негайно сповістити букмекерську\n            компанію. У разі потреби Клієнт зобов'язаний пред'явити Компанії\n            докази того, що несанкціонований доступ дійсний\n            стався. Букмекерська компанія не несе відповідальності за збитки,\n            отриманий Клієнтом внаслідок неправильного чи необережного\n            використання імені користувача та пароля третьою стороною або за\n            несанкціонований доступ до рахунку.\n          </span>\n        </p>\n        <p>\n          <span>\n            13. Депозити, розміщення та виведення коштів з рахунку\n          </span>\n        </p>\n        <p>\n          <span>\n            13.1. Для того, щоб зробити ставку на Веб-сайті, Клієнту необхідно\n            розмістити на своєму рахунку певну суму.\n          </span>\n        </p>\n        <p>\n          <span>13.2. Клієнт підтверджує та зобов'язується, що:</span>\n        </p>\n        <p>\n          <span>\n            13.2.1. кошти, внесені на ігровий рахунок, були\n            отримані незаконним чи забороненим шляхом;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.2.2. Клієнт не відмовлятиметься від скоєних транзакцій, не\n            заперечуватиме і скасовуватиме скоєні платежі, що може стати\n            причиною для повернення грошей третій стороні і дозволити їй уникнути\n            законної відповідальності.\n          </span>\n        </p>\n        <p>\n          <span>\n            13.3. Ми не приймаємо кошти від третіх осіб: друзів,\n            родичів чи партнерів. Клієнт зобов'язаний вносити кошти\n            тільки зі свого рахунку, банківської картки чи системи,\n            зареєстрованою на ім'я Клієнта. У разі виявлення фактів\n            порушення цієї умови всі виграші можуть бути конфісковані.\n          </span>\n        </p>\n        <p>\n          <span>\n            13.4. У разі запиту банківського переказу щодо повернення грошових коштів\n            коштів для їх законного власника всі витрати та комісії оплачуються\n            за рахунок одержувача.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.5. Ми не приймаємо платежі готівкою. Ми\n            можемо використовувати для електронних платежів, у тому числі вхідних\n            платежів та виплат Клієнтам, різні організації, що займаються\n            обробкою електронних платежів чи фінансові установи. За\n            винятком тих випадків, коли правила та умови даних установ\n            суперечать умовам Угоди, Клієнт повністю приймає такі\n            правила.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.6. Клієнт погоджується не відмовлятися, не анулювати та не\n            скасовувати транзакції, проведені за участю його рахунку. До того ж у\n            кожному з таких випадків Клієнт зобов'язаний повернути чи компенсувати\n            Компанії суму не розміщених коштів, включаючи витрати,\n            які ми можемо понести під час збору вкладів Клієнта.\n          </span>\n        </p>\n        <p>\n          <span>\n            13.7. Компанія має право блокувати рахунок Клієнта, а також\n            анулювати виплати та стягувати виграші, у разі виникнення\n            підозр щодо того, що поповнення рахунку було зроблено\n            шахрайським способом. Ми маємо право сповістити відповідні\n            органи про шахрайські дії з платежами та незаконною\n            діяльності. У нас є право вдаватися до послуг інкасуючих\n            агенцій для повернення платежів. Компанія не несе відповідальності за\n            несанкціоноване використання кредитних карток, незалежно від того\n            було заявлено про їхній крадіжку чи ні.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.8. Ми маємо право використовувати позитивний баланс рахунку Клієнта\n            для погашення грошової суми, яку Клієнт має відшкодувати\n            Компанії. Зокрема, у випадках повторних ставок або парі, згідно\n            пункту 10 («Змова, дії, що вводять в оману, шахрайство\n            та кримінальна діяльність) або пункту 13 («Помилки та\n            Недоліки»).&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.9. Клієнт повністю усвідомлює та приймає той факт, що ігровий\n            рахунок не є банківським рахунком. Отже, по відношенню до\n            ньому не діють методи страхування, поповнення, гарантії та інші\n            способи захисту з боку системи страхування вкладів та інших\n            систем страхування. На кошти на ігровому рахунку не\n            нараховуються відсотки.\n          </span>\n        </p>\n        <p>\n          <span>\n            13.10. Клієнт має право подати запит на виведення грошей з рахунку при\n            умови, що:\n          </span>\n        </p>\n        <p>\n          <span>\n            13.10.1 всі платежі, що надійшли на рахунок, пройшли перевірку, та жоден\n            їх не було скасовано чи анульовано;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.10.2 перевірочні дії були проведені належним чином.\n          </span>\n        </p>\n        <p>\n          <span>\n            13.11. При виконанні заявки на виведення коштів з рахунку повинні бути\n            враховано такі моменти:\n          </span>\n        </p>\n        <p>\n          <span>13.11.1. ігровий профіль має бути повністю заповнений;</span>\n        </p>\n        <p>\n          <span>\n            13.11.2. якщо у результаті запитаної операції виведення загальна сума\n            висновків коштів перевищує розмір 50 000 рублів. або\n            еквівалентну суму в будь-якій іншій валюті, то буде проведено\n            Процедура ідентифікації. Для її здійснення Клієнту необхідно\n            надіслати нам копію або цифрову фотографію документа,\n            посвідчує особу Клієнта. При поповненні рахунку за допомогою\n            кредитної картки, необхідно надіслати копію зображення обох сторін\n            цієї картки. У номері картки повинні бути видно перші шість і\n            останні чотири цифри, CVV2 код може бути прихований;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.11.3. компанія має право стягувати комісію на покриття витрат,\n            пов'язаних із виведенням коштів не задіяних у грі;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.11.4. сума виведення до 5 000 рублів або еквівалентна сума\n            іншій валюті, що виплачується на рахунок клієнта в строк від 1 до 60 хвилин\n            з моменту подання заявки, за винятком технічних неполадок з\n            сторони банку чи платіжної системи;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.11.5. сума виведення від 5 000 рублів або еквівалентна сума в\n            іншій валюті, що виплачується на рахунок клієнта протягом 5 днів з\n            моменту подання заявки;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.11.6. можливі інші затримки до 3-х робочих днів залежно\n            від банку чи іншої платіжної системи;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.11.7. інші шляхи виведення виграшних коштів обговорюються окремо\n            з Адміністрацією Веб-сайту.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.12. Компанія не надає послуги з обміну коштів.\n            У нас є право закривати подібні рахунки та:\n          </span>\n        </p>\n        <p>\n          <span>\n            13.12.1. утримувати комісію у розмірі наших витрат на виведення\n            засобів не задіяних у грі; &#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.12.2. визнавати недійсними всі транзакції, проведені з\n            використанням основного та дублюючих рахунків;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.12.3. не повертати Клієнтам усі вклади, зроблені з основного та\n            дублюючих рахунків.\n          </span>\n        </p>\n        <p>\n          <span>\n            13.13 Для активації висновків коштів гравцю необхідно\n            зробити ставки на суму щонайменше 100% від кожного внесеного депозиту\n            або щонайменше 100% від кожного внесеного депозиту задіяти\n            (грати, використовувати) у будь-яких іграх нашої платформи.\n          </span>\n        </p>\n        <p>\n          <span>\n            13.14. У випадку, якщо сума виграшу становить понад 5000000\n            (п'ять мільйонів рублів), букмекерська компанія залишає за собою\n            право встановити щоденний ліміт для висновку, що розраховується\n            індивідуально кожному за Клієнта.\n          </span>\n        </p>\n        <p>\n          <span>14. Умови та положення для послуг букмекерської компанії:</span>\n        </p>\n        <p>\n          <span>\n            14.1. Ви згодні сплатити всі послуги та/або товари або інші\n            додаткові послуги, які Ви замовили на Веб-сайті, а також всі\n            додаткові витрати (за потреби), включаючи, але не\n            обмежуючись, всілякі податки, мита тощо. Ви несете повну\n            відповідальність за своєчасну оплату всіх платежів. Провайдер\n            платіжних послуг забезпечує лише проведення платежу у зазначеному\n            Веб-сайтом розмірі та не несе відповідальності за сплату\n            користувачем Веб-сайту вищезгаданих додаткових сум. Після\n            натискання кнопки &quot;Оплата&quot;, вважається, що платіж оброблений,\n            і він безповоротно виконаний. Натиснувши кнопку &quot;Оплата&quot;, ви\n            погоджуєтесь з тим, що ви не зможете відкликати платіж або\n            вимагати його відкликання. Розміщуючи замовлення на сайті, ви підтверджуєте та\n            вказуєте, що не порушуєте закони будь-якої держави.\n            Додатково, приймаючи положення цих правил (і/або Умов та\n            положень), ви, як власник платіжної картки, підтверджуєте, що\n            маєте право користуватися товарами та/або послугами, що пропонуються на\n            Веб-сайті.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            14.2. Якщо ви використовуєте послуги Веб-сайту, що пропонує\n            такі специфічні послуги, як ігровий сервіс, ви надаєте\n            юридично зобов'язуюче підтвердження, що ви досягли або вже\n            перевищили вік повноліття, який є законодавчо\n            дозволеним у вашій юрисдикції для того, щоб користуватися послугами\n            наданими Веб-сайтом.\n          </span>\n        </p>\n        <p>\n          <span>\n            14.3. Починаючи користуватися послугами Веб-сайту, ви берете на себе\n            юридичну відповідальність за дотримання законодавства будь-якого\n            держави, де використовується дана послуга, та підтверджуєте, що\n            провайдер платіжних послуг не несе жодної відповідальності за будь-яке\n            незаконне чи несанкціоноване подібне порушення. Погоджуючись\n            використовувати послуги Веб-сайту, ви розумієте та приймаєте, що\n            обробка будь-якого вашого платежу здійснюється провайдером платіжних\n            послуг, і немає законного права повернення вже куплених\n            послуг та/або товарів або інших можливостей скасування платежу. Якщо ви\n            хочете відмовитися від використання послуги для наступної покупки\n            послуги та/або товарів, ви можете відмовитися від послуги, використовуючи\n            Особистий кабінет на Веб-сайті.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            14.4. Провайдер платіжних послуг не несе відповідальності за\n            відмова/неможливість обробити дані, пов'язані з вашою платіжною\n            карткою, або за відмову, пов'язану з неотриманням від банку-емітента\n            дозволу на проведення платежу з використанням вашої платіжної\n            картки. Провайдер платіжних послуг не несе відповідальності за\n            якість, обсяг, ціну будь-якої послуги та/або товару, запропонованих вам\n            або придбаних вами на Веб-сайті, використовуючи вашу платіжну картку.\n            Оплачуючи будь-які послуги та/або товари Веб-сайту, ви насамперед,\n            зобов'язані дотримуватись правил користування Веб-сайту. Просимо враховувати,\n            що тільки ви, як власник платіжної картки, несете відповідальність\n            за своєчасну оплату будь-якої послуги та/або товару, замовленої вами\n            через Веб-сайт та за всі пов'язані з цією оплатою додаткові\n            витрати/комісії. Провайдер платіжних послуг є тільки\n            виконавцем платежу у вказаному Веб-сайтом розмірі та не несе\n            відповідальність за будь-яке ціноутворення, загальні ціни та/або загальні\n            суми.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            14.5. У разі виникнення ситуації, пов'язаної з вашою незгодою\n            з вищевикладеними умовами та/або іншими причинами, просимо вас\n            своєчасно відмовитися від виконання платежу та, за необхідності,\n            звернутися безпосередньо до адміністратора/підтримки веб-сайту.\n          </span>\n        </p>\n        <p>\n          <span>\n            15. Змова, дії, що вводять в оману, шахрайство та\n            кримінальна діяльність&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.1. Компанія не рекомендує укладати парі групою Клієнтів з\n            однієї IP-адреси або з однієї локальної мережі, а також\n            попереднього узгодження. Вищезазначені дії можуть бути\n            розцінені як змова, шахрайство, дії, що вводять у\n            помилка.\n          </span>\n        </p>\n        <p>\n          <span>\n            15.2. Компанія не несе жодної відповідальності щодо того,\n            коли саме їй стало відомо або встановлено згодом, що\n            парі було укладено з порушенням правил. Ми маємо право закривати\n            подібні рахунки та:&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.2.1. визнавати недійсними усі транзакції, не повертати\n            Клієнтам усі вклади та ставки, зроблені узгоджено з іншими\n            Клієнтами;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.2.2. вимагати повернення всіх виграшів, бонусів та грошових\n            коштів, одержаних у результаті змови. Клієнт зобов'язаний повернути\n            їх на першу нашу вимогу.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.3. Наступні види діяльності суворо заборонені, вчинення\n            подібних дій буде розцінено як пряме порушення\n            Угоди:&#160;\n          </span>\n        </p>\n        <p>\n          <span>15.3.1. передача інформації третій стороні;</span>\n        </p>\n        <p>\n          <span>\n            15.3.2. незаконні дії: шахрайство, використання\n            шкідливих програм, ботів та помилок у програмному забезпеченні\n            Веб-сайту;&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.3.3. шахрайські дії, такі як використання вкрадених,\n            клонованих або отриманих іншим незаконним шляхом кредитних даних\n            або дебетової картки для поповнення рахунку;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.3.4. участь у злочинній діяльності, відмиванні грошей та інших\n            видах діяльності, участь у яких може спричинити\n            кримінально-правову відповідальність;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.4. У нас є право призупиняти, скасовувати чи відкликати\n            виплати, або виграші, пов'язані з бонусними коштами в тому\n            Якщо у нас з'явиться підозра в тому, що Клієнт навмисно\n            зловживає ними.\n          </span>\n        </p>\n        <p>\n          <span>\n            15.5. Компанія зробить усі допустимі та дозволені законом\n            дії для виключення та виявлення шахрайських змов та їх\n            безпосередніх учасників, а також проти цих осіб в обов'язковому\n            порядок буде вжито відповідних заходів. Ми не несемо\n            відповідальності за втрати та збитки, отримані Клієнтами в результаті\n            шахрайських дій.\n          </span>\n        </p>\n        <p>\n          <span>\n            15.6. Клієнти повинні негайно повідомити нас, якщо вони\n            виникнуть підозри щодо того, що якийсь Клієнт\n            перебуває у змові або здійснює шахрайські дії.\n            Зв'язатися з нами можна через звернення через Веб-сайт до служби\n            підтримки в режимі онлайн-чату або зателефонувавши за телефоном – 8 (800)\n            301-77-89 (цілодобово).&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.7. Ми маємо право без попереднього повідомлення заборонити\n            Клієнтам доступ до Веб-сайту та заблокувати їх рахунки, у тому випадку\n            якщо вони будуть запідозрені у шахрайській діяльності. У таких\n            випадках ми не несемо відповідальності щодо повернення та компенсації\n            грошових коштів, що є на рахунках таких Клієнтів. Крім того, у\n            нас є право сповістити правоохоронні органи про незаконну\n            діяльності. Клієнти повинні повністю співпрацювати з нами при\n            розслідуванні подібних випадків.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.8. Клієнтам заборонено використовувати послуги та програмне\n            забезпечення Веб-сайту для здійснення будь-яких шахрайських, незаконних\n            дій та транзакцій відповідно до законодавства будь-якої\n            конкретної юрисдикції. Якщо буде встановлено чи виявлено факт\n            здійснення Клієнтом подібних дій, то Компанія може\n            призупинити або заблокувати рахунок Клієнта та утримати кошти,\n            наявні на ньому. У таких випадках Клієнти не мають права пред'являти\n            Компанії будь-які претензії.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.9. На сайті заборонено здійснювати ігрову діяльність від імені\n            третіх осіб (номінальних власників ігрового рахунку).\n          </span>\n        </p>\n        <p>\n          <span>\n            Ігровий профіль підлягає негайному блокуванню, якщо в\n            процесі верифікації ігрового профілю співробітником служби\n            безпеки буде встановлено, що особа, яка проходить верифікацію не\n            має достатні знання в галузі ставок на спортивні\n            події.&#160;\n          </span>\n        </p>\n        <p>\n          <span>16. Інші заборонені дії на сайті&#160;</span>\n        </p>\n        <p>\n          <span>\n            16.1. На Веб-сайті заборонено використовувати агресивну або\n            образливу манеру спілкування, ненормативну лексику, погрози та\n            застосовувати будь-які насильницькі дії стосовно співробітників та\n            іншим Клієнтам Компанії. У разі недотримання Клієнтом цього пункту\n            правил, Компанія має право припинити комунікацію з цим Клієнтом\n            або залишити вхідну заявку без розгляду.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            16.2. Заборонено завантажувати на Веб-сайт інформацію в обсязі, здатному\n            викликати збої в роботі Веб-сайту, та здійснювати будь-які інші\n            дії, які можуть вплинути на роботу ресурсу. В даному випадку\n            маються на увазі віруси, шкідливі програми, масове розсилання та\n            спам - все перераховане суворо заборонено. Крім того, Клієнтам\n            заборонено видаляти, змінювати та редагувати інформацію, розміщену\n            на Веб-сайті.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            16.3. Клієнти можуть користуватися Веб-сайтом виключно в\n            розважальних цілях. Заборонено загалом або частково копіювати\n            Веб-сайт.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            16.4. Клієнти зобов'язуються не вчиняти дії, спрямовані на злам\n            системи безпеки Веб-сайту, отримання незаконного доступу до\n            закритим даним або DDoS-атаки. Стосовно Клієнтів,\n            запідозреним у порушенні цього правила, будуть застосовані\n            відповідні заходи: повна заборона на доступ до Веб-сайту та\n            блокування профілю. Крім того, ми маємо право сповістити\n            відповідальні органи про незаконні дії Клієнта.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            16.5. Ми не несемо відповідальності за втрати та збитки, які можуть\n            понести наші Клієнти або треті сторони внаслідок технічних\n            збоїв, спровокованих вірусними атаками чи іншими шкідливими\n            діями, спрямованими на Веб-сайт.\n          </span>\n        </p>\n        <p>\n          <span>\n            16.6. Строго заборонено передавати та продавати профіль одного Клієнта\n            іншому.&#160;\n          </span>\n        </p>\n        <p>\n          <span>17. Строки та порядок припинення дії Угоди&#160;</span>\n        </p>\n        <p>\n          <span>\n            17.1. Компанія має право видалити профіль Клієнта (а також його ім'я)\n            та пароль) без попереднього повідомлення у таких випадках:\n          </span>\n        </p>\n        <p>\n          <span>\n            17.1.1. Компанія прийняла рішення припинити надання Послуг\n            всім або певній частині Клієнтів; &#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            17.1.2. профіль Клієнта якимось чином пов'язаний із раніше віддаленим\n            профілем;\n          </span>\n        </p>\n        <p>\n          <span>\n            17.1.3. профіль Клієнта пов'язаний із заблокованим на даний час\n            профілем, у такому разі Компанія має право закрити профіль\n            незалежно від роду зв'язку та повністю заблокувати облікові дані\n            цих профілів. За винятком випадків, зазначених у Угоді,\n            кошти, що знаходяться на профілі Клієнта, будуть повернуті\n            йому протягом певного терміну, одразу після заповнення заявки та\n            утримання суми, яку Клієнт винен Компанії;\n          </span>\n        </p>\n        <p>\n          <span>\n            17.1.4. Клієнт бере участь у кримінальній змові або намагається\n            зламати систему;\n          </span>\n        </p>\n        <p>\n          <span>\n            17.1.5. Клієнт втручається у роботу програмного забезпечення\n            Веб-сайту або намагається проводити будь-які інші дії;\n          </span>\n        </p>\n        <p>\n          <span>\n            17.1.6. Клієнт використовує свій профіль для цілей, які можуть\n            розглядатися як незаконні згідно із законодавством будь-якої\n            конкретної юрисдикції;\n          </span>\n        </p>\n        <p>\n          <span>\n            17.1.7. Клієнт публікує на Веб-сайті інформацію образливого або\n            принизливого характеру.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            17.2. Компанія має право закрити профіль Клієнта або скасувати\n            дію Угоди, надіславши відповідне повідомлення на\n            електронну адресу, вказану в контактній інформації. У разі таких\n            дій з нашого боку, за винятком ситуацій, зазначених у пункті\n            15 («Змова, дії, що вводять в оману, шахрайство та\n            кримінальна діяльність») та 22 («Порушення умов») цього\n            Угоди, Компанія має повернути кошти з рахунку\n            Клієнта. Якщо з якихось причин ми не матимемо можливості\n            зв'язатися з Клієнтом, кошти будуть тимчасово переміщені на\n            рахунок букмекерської компанії чи контролюючого органу.\n          </span>\n        </p>\n        <p>\n          <span>18. Зміни на Веб-сайті</span>\n        </p>\n        <p>\n          <span>\n            18.1. Ми маємо право в будь-який час на власний розсуд,\n            вносити зміни або доповнення до послуг, які пропонуються на Веб-сайті\n            з метою підтримки та оновлення ресурсу.\n          </span>\n        </p>\n        <p>\n          <span>19. Системні помилки</span>\n        </p>\n        <p>\n          <span>\n            19.1. Якщо в процесі гри відбудеться збій у роботі Веб-сайту,\n            Компанія намагатиметься виправити ситуацію в найкоротші терміни. Ми не\n            несемо відповідальності за неполадки у засобах інформаційних\n            технологій, що виникли внаслідок роботи обладнання,\n            використовуваного Клієнтами для доступу до Веб-сайту, а також через збої в\n            роботі інтернет-провайдерів.\n          </span>\n        </p>\n        <p>\n          <span>20. Помилки та недоліки</span>\n        </p>\n        <p>\n          <span>\n            20.1. Компанія має право обмежувати чи скасовувати будь-які ставки.\n          </span>\n        </p>\n        <p>\n          <span>\n            20.2. Якщо Клієнт використав кошти, що надійшли на нього\n            рахунок в результаті помилки, для розміщення ставок та участі у грі, ми\n            можемо анулювати подібні ставки та будь-які виграші, отримані з них\n            допомогою. Якщо за такими ставками було здійснено виплату грошових коштів\n            коштів, то дані суми слід вважати переданими Клієнту в\n            довірче управління, Клієнт зобов'язаний повернути їх по першому\n            нашої вимоги.\n          </span>\n        </p>\n        <p>\n          <span>\n            20.3. Компанія та постачальники послуг не несуть відповідальності за шкоду,\n            у тому числі втрату виграшів, що стався внаслідок помилок з\n            сторони Клієнта чи з нашого боку.\n          </span>\n        </p>\n        <p>\n          <span>\n            20.4. Компанія, її дистриб'ютори, філії, ліцензіати, дочірні\n            підприємства, а також співробітники та керівники не несуть\n            відповідальності за будь-які збитки та збитки, що виникли з причини\n            перехоплення або неправильного використання&#160;\n          </span>\n        </p>\n        <p>\n          <span>інформації, що передається через Інтернет.&#160;</span>\n        </p>\n        <p>\n          <span>21. Обмеження нашої ответственности&#160;</span>\n        </p>\n        <p>\n          <span>\n            21.1. Клієнт самостійно приймає рішення щодо використання послуг.\n            Веб-сайту та будь-які дії та їх наслідки є наслідком\n            особистого вибору Клієнта, зробленого на його розсуд на власний\n            страх та ризик.\n          </span>\n        </p>\n        <p>\n          <span>\n            21.2. Робота Веб-сайту здійснюється у відповідність до пунктів\n            цієї Угоди. Компанія не надає жодних додаткових\n            гарантій або запевнень щодо Веб-сайту та послуг, які\n            пропонуються на ньому, і цим виключає свою відповідальність (у\n            ступеня, передбаченого законом) щодо всіх, що мають на увазі\n            гарантій.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            21.3. Ми не несемо відповідальності за правопорушення, недбалість,\n            збитки та збитки, які не можуть бути передбачені в даний\n            момент.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            21.4. Компанія не несе відповідальності за зміст ресурсів,\n            доступ до яких можна отримати за допомогою Веб-сайту.\n          </span>\n        </p>\n        <p>\n          <span>22. Порушення умов</span>\n        </p>\n        <p>\n          <span>\n            22.1. Клієнт дає свою згоду повною мірою відшкодовувати збитки,\n            захищати та відстоювати інтереси Компанії, її партнерів, співробітників та\n            директорів від будь-яких домагань, відповідальності, витрат, втрат та\n            витрат, що виникли через:&#160;\n          </span>\n        </p>\n        <p>\n          <span>22.1.1. порушення Клієнтом умов Угоди;</span>\n        </p>\n        <p>\n          <span>22.1.2. порушення Клієнтом законів та прав третіх осіб;</span>\n        </p>\n        <p>\n          <span>\n            22.1.3. отримання доступу до послуг Веб-сайту будь-якою іншою особою при\n            допомоги ідентифікаційних даних Клієнта з його дозволу або без\n            нього, або;\n          </span>\n        </p>\n        <p>\n          <span>22.1.4. присвоєння виграшів, одержаних таким шляхом.</span>\n        </p>\n        <p>\n          <span>\n            22.2. Якщо Клієнт порушить умови Угоди, ми маємо\n            право:\n          </span>\n        </p>\n        <p>\n          <span>\n            22.2.1. повідомити Клієнта про те, що своїми діями він порушує\n            умови Угоди, та вимагати негайного припинення\n            заборонених дій;\n          </span>\n        </p>\n        <p>\n          <span>22.2.2. призупинити дію рахунку Клієнта; &#160;</span>\n        </p>\n        <p>\n          <span>\n            22.2.3. заблокувати рахунок Клієнта без попереднього повідомлення;\n          </span>\n        </p>\n        <p>\n          <span>\n            22.2.4. стягнути з рахунку Клієнта суму виплат, виграшів або\n            бонусів, придбаних унаслідок порушення.\n          </span>\n        </p>\n        <p>\n          <span>\n            22.3. У нас є право анулювати ім'я користувача та пароль\n            Клієнта у разі недотримання ним будь-якого з пунктів Угоди.\n          </span>\n        </p>\n        <p>\n          <span>23. Права на об'єкти інтелектуальної власності</span>\n        </p>\n        <p>\n          <span>\n            23.1. Весь зміст Веб-сайту є об'єктом авторського права та\n            інших прав власності, що належать Компанії. Всі завантажувані та\n            друковані матеріали, присутні на Веб-сайті, можуть бути завантажені\n            лише на один комп'ютер. Роздруковувати ці матеріали дозволено\n            виключно з метою особистого та некомерційного використання.\n          </span>\n        </p>\n        <p>\n          <span>\n            23.2. Користування Веб-сайтом не дає Клієнту жодних прав на\n            інтелектуальну власність, що належить Компанії або третій\n            стороні.\n          </span>\n        </p>\n        <p>\n          <span>\n            23.3. Забороняється будь-яке використання чи відтворення торгової\n            марки, товарних знаків, логотипів та інших рекламних матеріалів,\n            представлених на Веб-сайті, без відповідної згоди Компанії.\n          </span>\n        </p>\n        <p>\n          <span>\n            23.4. Клієнт понесе відповідальність за будь-які збитки, витрати або\n            витрати, що виникли внаслідок здійснення ним забороненої\n            діяльності. Клієнти повинні негайно сповістити Компанію якщо\n            їм стане відомо про вчинення будь-якої забороненої діяльності\n            та надати всю необхідну допомогу у проведенні розслідування, яке\n            Компанія може провести з урахуванням наданої інформації.\n          </span>\n        </p>\n        <p>\n          <span>24. Персональні дані Клієнтів</span>\n        </p>\n        <p>\n          <span>\n            24.1. Ми зобов'язані дотримуватись вимог до захисту персональних даних у\n            тому вигляді, в якому Компанія використовує особисту інформацію, зібрану\n            в результаті візиту користувача на Веб-сайт. Компанія з\n            максимальною серйозністю належить до зобов'язань з обробки\n            персональних даних наших клієнтів. Компанія обробляє\n            персональні дані, надані Клієнтами з повним дотриманням\n            політики конфіденційності.\n          </span>\n        </p>\n        <p>\n          <span>\n            24.2. Надаючи персональні дані, Клієнти погоджуються з тим,\n            що у Компанії є право на обробку персональних даних для\n            цілей, зазначених у Угоді, або для дотримання нормативних та\n            юридичних&#160;\n          </span>\n        </p>\n        <p>\n          <span>зобов'язань.</span>\n        </p>\n        <p>\n          <span>\n            24.3. Відповідно до політики конфіденційності, ми зобов'язуємося не\n            розкривати та не передавати персональні дані наших Клієнтів\n            третім особам, за винятком систем обробки інформації та\n            працівників, які за потребою можуть використовувати її\n            виключно з метою якіснішого надання послуг.\n            24.4. Ми зберігаємо копії всієї кореспонденції, отриманої від Клієнтів,\n            щоб точно зафіксувати всю отриману інформацію.\n          </span>\n        </p>\n        <p>\n          <span>25. Використання файлів cookie на веб-сайті</span>\n        </p>\n        <p>\n          <span>\n            25.1. Ми використовуємо файли cookie для забезпечення функціональності\n            Веб-сайту. Cookie – це спеціальний текстовий файл невеликого\n            розміру, який зберігається на комп'ютері користувача при\n            відвідуванні Веб-сайту, за його допомогою ми можемо дізнаватися конкретних\n            користувачів при повторному відвідуванні веб-сайту. Додаткові\n            відомості про контроль та видалення файлів cookie можна знайти на сайті:\n            www.aboutcookies.org. Слід враховувати, що видалення файлів\n            \"Cookie\" може стати причиною блокування доступу до деяких\n            розділів та функцій Веб-сайту.\n          </span>\n        </p>\n        <p>\n          <span>26. Скарги та повідомлення</span>\n        </p>\n        <p>\n          <span>\n            26.1. У разі виникнення будь-яких скарг та претензій щодо роботи\n            Веб-сайту, перш за все, слід у найкоротші терміни направити свою\n            претензію до служби підтримки в режимі онлайн-чату через Веб-сайт\n            Компанії (телефон цілодобової підтримки Компанії – 8 (800)\n            301-77-89) або на електронну адресу компанії -\n            support@imbalance.click.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            26.2. Клієнт погоджується з тим, що запис розбіжності, що зберігається\n            на сервері, може бути використана як свідчення при\n            розгляд претензії.\n          </span>\n        </p>\n        <p>\n          <span>27. Порядок вирішення спірних ситуацій</span>\n        </p>\n        <p>\n          <span>\n            27.1. Гравець може заперечувати будь-які ситуації. Компанія всебічно та\n            об'єктивно розглядає всі спірні моменти у разі надання\n            конкретної інформації – фактів та доказів. Спірну інформацію, з\n            додатком фактів та доводів, необхідно надати у письмовому\n            у режимі онлайн-чату через Веб-сайт Компанії (тел.\n            цілодобової підтримки Компанії – 8(800)301-77-89) або на\n            електронна адреса служби підтримки компанії – security@imbalance.click. У\n            протягом 14 днів з моменту отримання листа скарги чи побажання\n            будуть розглянуті, і Клієнт отримає повідомлення про результат\n            розгляду у листі у відповідь. При необхідності проведення\n            додаткових перевірок, Компанія має право продовжити термін розгляду\n            звернення до 30 днів із моменту його отримання. У тексті листа\n            заборонено використовувати ненормативну лексику, будь-якого виду\n            образи та хибні дані.&#160;\n          </span>\n        </p>\n        <p>\n          <span>28. Обставини непереборної сили&#160;</span>\n        </p>\n        <p>\n          <span>\n            28.1. Компанія не несе відповідальності за затримки чи невиконання\n            зобов'язань, перелічених у Угоді, у разі, якщо вони\n            обумовлені обставинами непереборної сили, під якими\n            слід розуміти стихійні лиха, війни, громадянські хвилювання,\n            трудові суперечки, перебої у громадських комунальних мережах,\n            DDoS-атаки або інші атаки в мережі Інтернет, здатні надати\n            негативний вплив на роботу Веб-сайту.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            28.2. У період дії обставин непереборної сили\n            діяльність Веб-сайту вважається припиненою, і протягом\n            цього періоду у виконанні зобов'язань діє відстрочка.\n            Компанія зобов'язується використовувати всі доступні їй засоби для пошуку\n            рішень, що дозволяють повною мірою виконувати свої зобов'язання\n            перед Клієнтами, аж до закінчення дії обставин\n            непереборної сили.&#160;\n          </span>\n        </p>\n        <p>\n          <span>29. Відмова від зобов'язань&#160;</span>\n        </p>\n        <p>\n          <span>\n            29.1. Якщо ми не зможемо забезпечити виконання Клієнтом будь-якого\n            із зобов'язань або ми самі не зможемо скористатися будь-яким із\n            засобів правового захисту, на які ми маємо право, то це не\n            слід розцінювати як відмову від даних засобів правового захисту або\n            як причину, що звільняє Клієнта від виконання зобов'язань.\n          </span>\n        </p>\n        <p>\n          <span>30. Подільність угоди&#160;</span>\n        </p>\n        <p>\n          <span>\n            30.1. Якщо будь-який з пунктів Угоди стане недійсним,\n            нелегітимним або таким, що втратив юридичну силу, то дане положення\n            буде відокремлено від решти Угоди, яка повною мірою\n            збереже свою юридичну силу. У таких випадках частина, яка\n            вважається недійсною, буде змінена відповідно до оновлених\n            норм.\n          </span>\n        </p>\n        <p>\n          <span>31. Посилання&#160;</span>\n        </p>\n        <p>\n          <span>\n            31.1. На Веб-сайті можуть бути посилання на інші ресурси,\n            які знаходяться поза нашим контролем. Ми не несемо відповідальності\n            за зміст інших сайтів, дії чи бездіяльність їх власників\n            та за зміст реклами третьої сторони та спонсорства. Гіперпосилання\n            на інші сайти надаються виключно в інформаційних\n            цілях. Клієнти використовують їх на власний страх та ризик.&#160;\n          </span>\n        </p>\n        <p>\n          <span>32. Бонусні акції&#160;</span>\n        </p>\n        <p>\n          <span>\n            32.1. Підвищений вейджер (відіграш) встановлюється лише на\n            грошові бонуси та поширюється тільки на суму бонусу. Якщо\n            бонус є відсотком від депозиту, то вейджер поширюється на\n            суму відсотка. Розмір вейджера залежить від бонусної акції, що проводиться.\n            та встановлюється Веб-сайтом.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            32.2. Вивести грошовий бонус можна лише за умови його повного\n            відіграшу.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            При нарахуванні грошових бонусів за реєстрацію чи інших випадках,\n            коли при отриманні бонусу від Клієнта не потрібне внесення коштів\n            на баланс, виведення бонусного нарахування неможливе до першого\n            депозиту.\n          </span>\n        </p>\n      </div>\n";
export default html;
